<!--
  上传视频组件 - UploadVideo
  
  实现思路：
  1. 组件状态管理：维护上传状态（空闲、上传中、上传成功、上传失败）
  2. 文件处理：支持拖拽、点击和粘贴三种上传方式，验证文件类型和大小
  3. 视频预览：参考left-panel的视频控制界面设计
  4. 交互逻辑：空状态可点击上传，有视频状态点击播放，支持删除重新上传
  5. 事件处理：上传成功后通过 emit 向父组件传递结果
  
  功能特性：
  - 支持拖拽、点击、粘贴上传
  - 文件类型验证（仅支持视频格式）
  - 文件大小验证（默认最大50MB）
  - 视频预览和播放控制
  - 响应式设计
-->

<template>
    <div 
      ref="containerRef"
      class="upload-video-container"
      :class="{
        'empty-state': !isUploading && !isUploaded,
        'has-video': isUploaded,
        'drag-over': isDragOver,
        'uploading': isUploading
      }"
      :style="convertStyleObject({ width: width, height: height })"
      @drop="handleDrop"
      @dragover.prevent="handleDragOver"
      @dragleave="handleDragLeave"
      @click="handleClick"
    >
      <!-- 粘贴提示 -->
      <div class="paste-hint" :class="{ show: showPasteHint }">
        {{ t('pasteVideoHint') }}
      </div>
      
      <!-- 空状态 - 显示上传提示 -->
      <div v-if="!isUploading && !isUploaded" class="upload-placeholder">
        <!-- 上传图标 -->
        <div class="upload-icon">
          <l-img 
            src="/static/images/video_placeholder_icon.png" 
            w="40px" 
            h="40px" 
          />
        </div>
        
        <!-- 主要提示文字 -->
        <div class="upload-text-primary">
          {{ t('clickOrDragToUploadVideo') }}
        </div>
        
        <!-- 辅助提示文字 -->
        <div class="upload-text-secondary">
          {{ t('videoSizeLimit', { size: maxSize }) }}
        </div>
        
        <!-- 粘贴提示 -->
        <div class="paste-tip">
          {{ t('orPasteVideo') }}
        </div>
      </div>
  
      <!-- 上传中状态 -->
      <div v-if="isUploading" class="upload-loading">
        <div class="loading-icon">
          <l-img src="/static/images/file_loading.png" w="40px" h="40px" />
        </div>
        <div class="loading-text">
          {{ t('videoUploading') }}
        </div>
      </div>
  
      <!-- 上传成功状态 - 显示视频预览 -->
      <div v-if="isUploaded && videoPreviewUrl" class="upload-success">
        <!-- 视频预览容器 -->
        <div class="video-wrapper" @click.stop>
          <l-video 
            ref="videoRef"
            custom-class="preview-video"
            :src="videoPreviewUrl"
            :poster="props.defaultPoster"
            @click="toggleVideo"
            @loadeddata="handleVideoLoaded"
            @play="handleVideoPlay"
            @pause="handleVideoPause"
            @ended="handleVideoEnded"
            @error="handleVideoError"
          >
          </l-video>
          
          <!-- 视频控制覆盖层 -->
          <!-- <div class="video-overlay" @click.stop>
            <div class="video-controls">
              <div class="control-left">
                <l-img 
                  @click="toggleVideo"
                  v-show="isVideoPlaying"
                  src="/static/images/pause-icon.png" 
                  w="24px" 
                  h="24px" 
                  class="video-control-icon"
                />
                <l-img 
                  @click="toggleVideo"
                  v-show="!isVideoPlaying"
                  src="/static/images/play-icon.png" 
                  w="24px" 
                  h="24px" 
                  class="video-control-icon"
                />
                <span class="video-time">{{ formattedCurrentTime }} / {{ formattedDuration }}</span>
              </div>
              
              <l-img 
                src="/static/images/expand-icon.png" 
                w="20px" 
                h="20px" 
                @click="fullScreen" 
                class="video-control-icon" 
              />
            </div>
          </div> -->
        </div>
        
        <!-- 删除按钮 -->
        <div class="delete-icon" @click.stop="handleDeleteVideo">
          <l-img 
            src="/static/images/close_icon.png" 
            w="24px" 
            h="24px" 
          />
        </div>
      </div>
  
      <!-- 隐藏的文件输入框 -->
      <input 
        ref="fileInputRef"
        type="file"
        accept="video/*"
        @change="handleFileSelect"
        style="display: none"
      />
    </div>
  </template>
  
  <script setup>
  import { ref, computed, onMounted, onUnmounted, watch } from 'vue';
  import { useI18n } from 'vue-i18n';
  import LImg from '@/components/l-img.vue';
  import { showMessageError, showMessageSuccess } from '@/utils/ui-feedback';
  import { convertStyleObject } from '@/utils/px-to-rem';
  import LVideo from '../l-video.vue';
  
  // 组件属性定义
  const props = defineProps({
    // 组件宽度，默认100%
    width: {
      type: String,
      default: '100%'
    },
    // 组件高度，默认240px
    height: {
      type: String,
      default: '240px'
    },
    // 最大文件大小（MB），默认50MB
    maxSize: {
      type: Number,
      default: 50
    },
    // 默认视频地址，如果有值则直接显示该视频
    defaultUrl: {
      type: String,
      default: ''
    },
    // 默认视频封面地址，用于在视频未播放时显示
    defaultPoster: {
      type: String,
      default: ''
    }
  });
  
  // 组件事件定义
  const emit = defineEmits(['uploadSuccess', 'deleteSuccess', 'uploadError']);
  
  // 多语言支持
  const { t } = useI18n();
  
  // 组件状态
  const containerRef = ref(null);
  const fileInputRef = ref(null);
  const videoRef = ref(null);
  const isDragOver = ref(false);
  const isUploading = ref(false);
  const isUploaded = ref(false);
  const videoPreviewUrl = ref('');
  const showPasteHint = ref(false);
  
  // 视频播放相关状态
  const isVideoPlaying = ref(false);
  const currentTime = ref(0);
  const duration = ref(0);
  const isVideoLoaded = ref(false);
  
  // 支持的视频格式
  const ALLOWED_VIDEO_TYPES = [
    'video/mp4',
    'video/avi',
    'video/mov',
    'video/wmv',
    'video/flv',
    'video/webm',
    'video/quicktime'
  ];
  
  // 计算属性
  const formattedCurrentTime = computed(() => {
    return formatTime(currentTime.value);
  });
  
  const formattedDuration = computed(() => {
    return formatTime(duration.value);
  });
  
  // 格式化时间
  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };
  
  /**
   * 验证文件是否符合要求
   * @param {File} file - 要验证的文件
   * @returns {boolean} - 验证结果
   */
  const validateFile = (file) => {
    // 检查文件类型
    if (!ALLOWED_VIDEO_TYPES.includes(file.type)) {
      showMessageError(t("videoTypeNotAllowed"));
      return false;
    }
  
    // 检查文件大小
    const maxSizeBytes = props.maxSize * 1024 * 1024; // 转换为字节
    if (file.size > maxSizeBytes) {
      showMessageError(t('videoSizeExceeded'));
      return false;
    }
  
    return true;
  };
  
  /**
   * 处理文件上传
   * @param {File} file - 要上传的文件
   */
  const handleFileUpload = async (file) => {
    if (!validateFile(file)) {
      return;
    }
  
    try {
      // 清理旧的预览URL
      if (videoPreviewUrl.value && videoPreviewUrl.value.startsWith('blob:')) {
        URL.revokeObjectURL(videoPreviewUrl.value);
      }
  
      // 设置上传状态
      isUploading.value = true;
      isUploaded.value = false;
      resetVideoState();
  
      // 创建预览URL
      videoPreviewUrl.value = URL.createObjectURL(file);
  
      // 模拟上传过程（实际项目中这里会调用真实的上传API）
      await new Promise(resolve => setTimeout(resolve, 1500));
  
      // 上传成功
      isUploading.value = false;
      isUploaded.value = true;
  
      // 通知父组件上传成功
      emit('uploadSuccess', {
        url: videoPreviewUrl.value,
        file: file,
        duration: duration.value || 0
      });
  
      showMessageSuccess(t('videoUploadSuccess'));
  
    } catch (error) {
      console.error('Video upload failed:', error);
      
      // 重置状态
      resetAllState();
  
      // 显示错误提示
      showMessageError(t('videoUploadFailed'));
      emit('uploadError', error);
    }
  };

  /**
   * 初始化默认视频
   */
  const initDefaultVideo = () => {
    if (props.defaultUrl) {
      videoPreviewUrl.value = props.defaultUrl;
      isUploaded.value = true;
      isUploading.value = false;
      
      // 通知父组件默认视频加载成功
      emit('uploadSuccess', {
        url: props.defaultUrl,
        file: null,
        duration: 0,
        isDefault: true
      });
    }
  };
  
  /**
   * 重置视频播放状态
   */
  const resetVideoState = () => {
    isVideoPlaying.value = false;
    currentTime.value = 0;
    duration.value = 0;
    isVideoLoaded.value = false;
  };
  
  /**
   * 重置所有状态
   */
  const resetAllState = () => {
    isUploading.value = false;
    isUploaded.value = false;
    resetVideoState();
    
    // 清理blob URL
    if (videoPreviewUrl.value && videoPreviewUrl.value.startsWith('blob:')) {
      URL.revokeObjectURL(videoPreviewUrl.value);
    }
    videoPreviewUrl.value = '';
  };
  
  /**
   * 处理点击上传
   */
  const handleClick = () => {
    // 只在空状态下才能点击上传
    if (isUploading.value || isUploaded.value) return;
    fileInputRef.value?.click();
  };
  
  /**
   * 处理文件选择
   * @param {Event} event - 文件选择事件
   */
  const handleFileSelect = (event) => {
    const file = event.target.files?.[0];
    if (file) {
      handleFileUpload(file);
    }
    // 重置文件输入框，允许重复选择同一文件
    event.target.value = '';
  };
  
  /**
   * 处理拖拽进入
   * @param {DragEvent} event - 拖拽事件
   */
  const handleDragOver = (event) => {
    event.preventDefault();
    if (!isUploading.value && !isUploaded.value) {
      isDragOver.value = true;
    }
  };
  
  /**
   * 处理拖拽离开
   */
  const handleDragLeave = () => {
    isDragOver.value = false;
  };
  
  /**
   * 处理文件拖拽释放
   * @param {DragEvent} event - 拖拽释放事件
   */
  const handleDrop = (event) => {
    event.preventDefault();
    isDragOver.value = false;
    
    if (isUploading.value || isUploaded.value) return;
    
    const files = event.dataTransfer?.files;
    if (files && files.length > 0) {
      handleFileUpload(files[0]);
    }
  };
  
  /**
   * 处理粘贴事件
   * @param {ClipboardEvent} event - 粘贴事件
   */
  const handlePaste = async (event) => {
    if (isUploading.value || isUploaded.value) return;
    
    const items = event.clipboardData?.items;
    if (!items) return;
    
    for (let item of items) {
      if (item.type.startsWith('video/')) {
        event.preventDefault();
        const file = item.getAsFile();
        if (file) {
          await handleFileUpload(file);
          break;
        }
      }
    }
  };
  
  /**
   * 处理键盘事件，显示粘贴提示
   * @param {KeyboardEvent} event - 键盘事件
   */
  const handleKeyDown = (event) => {
    if (!isUploading.value && !isUploaded.value) {
      if ((event.ctrlKey || event.metaKey) && event.key === 'v') {
        showPasteHint.value = true;
        setTimeout(() => {
          showPasteHint.value = false;
        }, 2000);
      }
    }
  };
  
  /**
   * 处理删除视频
   */
  const handleDeleteVideo = (event) => {
    event.stopPropagation();
    
    // 清理blob URL
    if (videoPreviewUrl.value && videoPreviewUrl.value.startsWith('blob:')) {
      URL.revokeObjectURL(videoPreviewUrl.value);
    }
    
    // 重置所有状态
    isUploading.value = false;
    isUploaded.value = false;
    resetVideoState();
    videoPreviewUrl.value = '';
    
    // 重置文件输入框
    if (fileInputRef.value) {
      fileInputRef.value.value = '';
    }
    
    emit('deleteSuccess');
  };
  
  // 视频播放控制相关方法
  const handleVideoLoaded = () => {
    if (videoRef.value) {
      duration.value = videoRef.value.duration || 0;
      isVideoLoaded.value = true;
    }
  };
  
  const handleVideoPlay = () => {
    isVideoPlaying.value = true;
    startTimeUpdate();
  };
  
  const handleVideoPause = () => {
    isVideoPlaying.value = false;
  };
  
  const handleVideoEnded = () => {
    isVideoPlaying.value = false;
    currentTime.value = 0;
  };
  
  const handleVideoError = () => {
    showMessageError('Failed to load video');
  };
  
  const toggleVideo = (event) => {
    event.stopPropagation();
    if (!videoRef.value || !isVideoLoaded.value) return;
  
    if (isVideoPlaying.value) {
      videoRef.value.pause();
    } else {
      videoRef.value.play();
    }
  };
  
  const fullScreen = (event) => {
    event.stopPropagation();
    if (videoRef.value && videoRef.value.requestFullscreen) {
      videoRef.value.requestFullscreen();
    }
  };
  
  const startTimeUpdate = () => {
    const updateTime = () => {
      if (videoRef.value && isVideoPlaying.value) {
        currentTime.value = videoRef.value.currentTime;
        requestAnimationFrame(updateTime);
      }
    };
    updateTime();
  };
  watch(props, (newVal) => {
    if (newVal.defaultUrl&&!videoPreviewUrl.value) {
      initDefaultVideo();
    }
  });
  
  // 组件挂载时添加事件监听
  onMounted(() => {
    if (containerRef.value) {
      // 让容器可以获得焦点以接收paste事件
      containerRef.value.tabIndex = 0;
      containerRef.value.addEventListener('paste', handlePaste);
    }
    
    // 添加键盘事件监听
    document.addEventListener('keydown', handleKeyDown);
    
    // 初始化默认视频
    initDefaultVideo();
  });
  
  // 组件卸载时清理资源
  onUnmounted(() => {
    if (containerRef.value) {
      containerRef.value.removeEventListener('paste', handlePaste);
    }
    
    document.removeEventListener('keydown', handleKeyDown);
    
    // 清理blob URL
    if (videoPreviewUrl.value && videoPreviewUrl.value.startsWith('blob:')) {
      URL.revokeObjectURL(videoPreviewUrl.value);
    }
  });
  
  // 暴露方法给父组件
  defineExpose({
    handleDeleteVideo,
    resetAllState
  });
  </script>
  
